import type { TableProps } from "./table.types";
import type { CSSObject } from "@emotion/react";

import { SelectClasses } from "@components/select";
import { CellClasses } from "@components/cell";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { ComponentProps } from "@types";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Table";

// Generate child element class names for the component, should match available style slots
export const TableClasses = {
  root: "exp-textura_table_root",
  tableContainer: "exp-textura_table_container",
  table: "exp-textura_table",
  header: "exp-textura_table_header",
  headerRow: "exp-textura_table_header_row",
  headerCell: "exp-textura_table_header_cell",
  headerCellContent: "exp-textura_table_header_cell_content",
  body: "exp-textura_table_body",
  bodyRow: "exp-textura_table_body_row",
  bodyCell: "exp-textura_table_body_cell",
  bodySubRow: "exp-textura_table_body_sub_row",
  footer: "exp-textura_table_footer",
  toolbar: "exp-textura_table_toolbar",
  toolbarTrailing: "exp-textura_table_toolbar_trailing",
  filterIconButton: "exp-textura_table_filter_icon_button",
  searchInput: "exp-textura_table_search_input",
  pageSizeSelect: "exp-textura_table_page_size_select",
  filterChipBars: "exp-textura_table_filter_chip_bar",
  emptyState: "exp-textura_table_empty_state",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

type TableStyleProps = Pick<TableProps, "currentTheme" | "variant" | "styleSlots">;

const generateStyles = (props: TableStyleProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<TableProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[24]),

    [`.${TableClasses.toolbar}`]: {
      display: "flex",
      justifyContent: "flex-start",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      [`> .${SelectClasses.root}`]: {
        ...styleSlots?.toolbarSelectFilter,
      },
      ...styleSlots?.toolbar,
    },

    [`.${TableClasses.toolbarTrailing}`]: {
      display: "flex",
      justifyContent: "flex-end",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      marginInlineStart: "auto",
      ...styleSlots?.toolbarTrailing,
    },

    [`.${TableClasses.searchInput}`]: {
      width: theme.toRem(267),
      flex: 0,
      ...styleSlots?.searchInput,
    },

    [`.${TableClasses.filterIconButton}`]: {
      ...styleSlots?.filterIconButton,
    },

    [`.${TableClasses.filterChipBars}`]: {
      display: "flex",
      flex: 1,
      alignItems: "center",
      height: theme.toRem(28),
      gap: theme.toRem(theme.spacing[8]),
      ...theme.typography.label.md,
      fontSize: theme.typography.fontSize[14],
      color: theme.color.content.weak,
      ...styleSlots?.filterChipBars,
    },

    [`.${TableClasses.tableContainer}`]: {
      overflowX: "auto",
      ...styleSlots?.tableContainer,
    },

    [`.${TableClasses.table}`]: {
      width: "100%",
      borderCollapse: "collapse",
      tableLayout: "fixed",
      ...styleSlots?.table,
    },

    [`.${TableClasses.header}`]: {
      ...styleSlots?.header,
    },

    [`.${TableClasses.headerRow}`]: {
      ...styleSlots?.headerRow,
    },

    [`.${TableClasses.headerCell}`]: {
      ...theme.typography.body.mdEmphasis,
      whiteSpace: "nowrap",
      overflow: "hidden",
      textOverflow: "ellipsis",
      color: theme.color.content.weak,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[12])}`,
      textAlign: "start",
      borderTop: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      borderBottom: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      borderInlineEnd: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      "&:first-of-type": {
        borderInlineStart: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
        ...styleSlots?.headerCellFirstOfType,
      },
      "&:hover": {
        ...styleSlots?.headerCellHover,
      },
      "&:focus-visible": {
        outline: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.focus.default}`,
        outlineOffset: `calc(-1 * ${theme.toRem(theme.border.width.sm)})`,
        boxShadow: "none",
        ...styleSlots?.headerCellFocus,
      },
      "&[data-column-id='select'] > *": {
        justifyContent: "center",
        ...styleSlots?.headerSelectionColumn,
      },
      "&[data-column-id='expand']": {
        ...styleSlots?.headerExpandColumn,
      },
      ...styleSlots?.headerCell,
    },

    [`.${TableClasses.headerCellContent}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      gap: theme.toRem(theme.spacing[4]),
      "&[data-sort='true'] > svg": {
        minWidth: "1rem",
        ...styleSlots?.headerCellContentSortSvg,
      },
      "&[data-sort='false'] > svg": {
        color: theme.color.content.iconWeak,
        ...styleSlots?.headerCellContentNoSortSvg,
      },
      ...styleSlots?.headerCellContent,
    },

    [`.${TableClasses.body}`]: {
      ...styleSlots?.body,
    },

    [`.${TableClasses.bodyRow}`]: {
      "&[data-expanded='true']": {
        ...styleSlots?.bodyRowExpanded,
      },
      [`&.${TableClasses.bodySubRow}`]: {
        ...styleSlots?.bodySubRow,
      },
      ...styleSlots?.bodyRow,
    },

    [`.${TableClasses.bodyCell}`]: {
      ...theme.typography.body.md,
      whiteSpace: "nowrap",
      overflow: "hidden",
      textOverflow: "ellipsis",
      color: theme.color.content.default,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[12])}`,
      borderBottom: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      borderInlineEnd: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      "&:first-of-type": {
        borderInlineStart: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
        ...styleSlots?.bodyCellFirstOfType,
      },
      "&:hover": {
        ...styleSlots?.bodyCellHover,
      },
      "&:focus-visible": {
        outline: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.focus.default}`,
        outlineOffset: `calc(-1 * ${theme.toRem(theme.border.width.sm)})`,
        boxShadow: "none",
        ...styleSlots?.bodyCellFocus,
      },
      "&[data-column-id='select'] > *": {
        margin: "auto",
        ...styleSlots?.bodySelectionColumn,
      },
      "&[data-column-id='expand']": {
        textAlign: "center",
        width: theme.toRem(24),
        padding: 0,
        [`& .${CellClasses.expandToggle}`]: {
          justifyContent: "center",
        },
        ...styleSlots?.bodyExpandColumn,
      },
      [`& .${CellClasses.expandToggle}`]: {
        ...styleSlots?.expandToggle,
      },
      ...styleSlots?.bodyCell,
    },

    [`.${TableClasses.pageSizeSelect}`]: {
      width: "auto",
      marginInlineEnd: "auto",
      ...styleSlots?.pageSizeSelect,
    },

    [`.${TableClasses.footer}`]: {
      display: "flex",
      justifyContent: "flex-end",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      paddingTop: theme.toRem(theme.spacing[24]),
      ...styleSlots?.footer,
    },

    [`.${TableClasses.emptyState}`]: {
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      width: "100%",
      height: "100%",
      ...styleSlots?.emptyState,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();
export const StyledTable = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<React.HTMLAttributes<HTMLDivElement> & ComponentProps>((props) =>
  generateStyles(props as TableStyleProps),
);
